def Dequeue(Queue, Head, Tail, NumItems):
    if NumItems == 0:
        return (false, Queue, Head, Tail, NumItems)
    else:
        ReturnValue = Queue(Head)
        Head = Head + 1
        if Head >= 9:
            Head = 0
        NumItems = NumItems - 1
        return(ReturnValue, Queue, Head, Tail, NumItems)

