function ProcessMarks (mark:array of integer):integer;
  var highest, total, position, i: integer;
  average: real;
  begin
     highest := mark[1];
     total := 0;
     position := mark[1];
     for i := 1 to 20 do
        begin
           total := total + mark[1];
           if  mark[i] > highest then
           begin
              highest := mark[i];
              position := i;
           end;
        end;
     average := total / 20;
     writeln ('The average mark is ', average, ' and the highest mark is ',
highest);
     ProcessMarks := position;
  end;

