  repeat
  begin
     NoSwaps := TRUE
     for J := 1 to Boundary do
     begin
        if Contact[J] > Contact[J+1]then
        begin
           Temp := Contact[J];
           Contact[J] := Contact[J+1];
           Contact[J+1] := Temp;
