function extract(InString : string) : string;
var
   Name : string;
   NextChar : char;
   Index : integer;
const
  COLON = ':';
  Index := 1;
  Name := "";
  NextChar := copy(InString, 1, 1);
  While NextChar <> COLON do
  begin
     Name := Name & NextChar;
     Index := Index + 1;
     NextChar := copy(Instring, Index, 1);
  end;
  extract := Name;
end;

