Peocedure BubbleSort();
var
  Temp: Integer;
  NoSwaps : Boolean;
  Boundary, J : Integer;
begin
  Boundary := 4999;
  repeat
     NoSwaps := TRUE;
     for J := 1 To Boundary do
        begin
           if ProdNum[J] > ProdNum[J+1] then
              begin
                 Temp := ProdNum[J];
                 ProdNum[J] := ProdNum[J+1];
                 ProdNum[J+1] := Temp;
                 NoSwaps := FALSE;
              end;
        end;
     Boundary := Boundary – 1;
  until NoSwaps = TRUE;
end;

